			{
				"name": "quay.io/example/image",
				"digest": {
					"sha256": "abc123",
				},
			},
		],
		"predicate": {
			"buildConfig": {
				"tasks": [
					{
						"name": "build-container",
						"results": [
							{
								"name": "IMAGE_DIGEST",
								"type": "string",
								"value": "sha256:abc123",
							},
						],
					},
				],
			},
		},
	}
}

# Negative test: invalid input should produce at least one deny violation.
