					"sha256": "abc123",
				},
			},
			{
				"name": "quay.io/example/image2",
				"digest": {
					"sha256": "orphan999",
				},
			},
		],
		"predicate": {
			"buildConfig": {
				"tasks": [
					{
						"name": "build-container",
						"results": [
							{
								"name": "IMAGE_DIGEST",
